// TMDB <-> AniList <-> MyAnimeList ID resolution.
//
// TMDB knows nothing about anime tracking ids, and neither tracker knows about
// TMDB, so the bridge is a data file generated by scripts/build-anime-map.mjs from
// the community anime-lists dataset (MAL/AniList/AniDB/TVDB/TMDB crosswalk).
//
// The asset is lazy-loaded once per session (~161 KB) and only when a sync needs
// it, so it never sits on the critical path of a page render.
import type { AnimeItem } from "../types/anime";

const MAP_URL = "/anime-map.json";

type Ids = { m?: number; a?: number };
type MediaMap = { tv: Record<string, Ids>; movie: Record<string, Ids> };

export type MediaIds = {
  malId?: number;
  anilistId?: number;
};

let mapPromise: Promise<MediaMap | null> | null = null;

function loadMap(): Promise<MediaMap | null> {
  if (!mapPromise) {
    mapPromise = fetch(MAP_URL)
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json() as Promise<MediaMap>;
      })
      .catch((e) => {
        // Sync still works through AniList's idMal and title matching; the
        // crosswalk is an accelerator, not a requirement.
        console.warn("[media-ids] crosswalk unavailable:", e);
        return null;
      });
  }
  return mapPromise;
}

function bucketFor(item: AnimeItem): "tv" | "movie" {
  return item.type === "movie" ? "movie" : "tv";
}

/** Crosswalk lookup by TMDB id. Returns null when the title is not mapped. */
export async function lookupMediaIds(
  tmdbId: number | undefined | null,
  mediaType: "tv" | "movie",
): Promise<MediaIds | null> {
  if (!tmdbId) return null;
  const map = await loadMap();
  if (!map) return null;

  const ids = map[mediaType]?.[String(tmdbId)];
  if (!ids) return null;

  return {
    malId: typeof ids.m === "number" ? ids.m : undefined,
    anilistId: typeof ids.a === "number" ? ids.a : undefined,
  };
}

/**
 * Best-known ids for an item: ids already stored on it win, then the crosswalk.
 * A stored id is authoritative because it came from a real API response.
 */
export async function resolveMediaIds(item: AnimeItem): Promise<MediaIds> {
  const stored: MediaIds = { malId: item.malId, anilistId: item.anilistId };
  if (stored.malId || stored.anilistId) return stored;

  const mapped = await lookupMediaIds(item.tmdbId ?? item.id, bucketFor(item));
  return {
    malId: stored.malId ?? mapped?.malId,
    anilistId: stored.anilistId ?? mapped?.anilistId,
  };
}
